-- composition of rule kernels join_filter_pushdown x partitioned_execution (duckdb), template exists
SET max_execution_time=10000;
EXPLAIN (FORMAT JSON) WITH RECURSIVE nodes(i, h) AS MATERIALIZED ( SELECT i, i % 3 FROM range(256) t(i) ), walks(i, h, step) AS ( SELECT i, h, 0 FROM nodes WHERE i = 128 UNION ALL SELECT n.i, n.h, w.step + 1 FROM (VALUES (-1), (1)) d(delta) JOIN walks w ON true JOIN nodes n ON w.i + d.delta = n.i AND w.h <= n.h + 1 WHERE w.step < 6 ) SELECT count(*), sum(i), sum(h), max(step) FROM walks;
EXPLAIN (FORMAT JSON) WITH RECURSIVE nodes(i, h) AS MATERIALIZED ( SELECT i, i % 3 FROM range(256) t(i) ), walks(i, h, step) AS ( SELECT i, h, 0 FROM nodes WHERE i = 128 UNION ALL SELECT n.i, n.h, w.step + 1 FROM (VALUES (-1), (1)) d(delta) JOIN (SELECT * FROM walks) w ON true JOIN nodes n ON w.i + d.delta = n.i AND w.h <= n.h + 1 WHERE w.step < 6 ) SELECT count(*), sum(i), sum(h), max(step) FROM walks;
EXPLAIN (FORMAT JSON) WITH RECURSIVE nodes(i, h) AS MATERIALIZED ( SELECT i, i % 3 FROM range(256) t(i) ), walks(i, h, step) AS ( SELECT i, h, 0 FROM nodes WHERE i = 128 UNION ALL SELECT n.i, n.h, w.step + 1 FROM (VALUES (-1), (1)) d(delta) JOIN (SELECT i, h, step FROM (SELECT * FROM walks WHERE i IS NOT NULL) filtered) w ON true JOIN nodes n ON w.i + d.delta = n.i AND w.h <= n.h + 1 WHERE w.step < 6 ) SELECT count(*), sum(i), sum(h), max(step) FROM walks;
SET disabled_optimizers='build_side_probe_side';
EXPLAIN (FORMAT JSON) WITH RECURSIVE r(i) AS ( VALUES (0) UNION ALL SELECT x.i + 1 FROM range(1000) n(i) JOIN (SELECT * FROM r) x ON x.i = n.i JOIN range(3) tiny(j) ON tiny.j = n.i WHERE x.i < 3 ) SELECT count(*), sum(i) FROM r;
RESET disabled_optimizers;
SELECT count(*) FROM (WITH nodes(i, h) AS MATERIALIZED ( SELECT i, i FROM range(256) t(i) ), frontier(i, h) AS MATERIALIZED (VALUES (128, 2)) SELECT* FROM (VALUES (1)) d(delta) JOIN ( FROM frontier) w ON true JOIN nodes n ON w.i + d.delta = n.i AND w.h <= n.h + 1) AS ka WHERE EXISTS (SELECT 1 FROM (WITH RECURSIVE rc(c0) AS (SELECT 1 UNION ALL SELECT r.c0 + 1 FROM rc AS r WHERE r.c0 < 100) SELECT ARRAY['1'::text] AS c0, 1.0::float8 AS c1, a1.c3 AS c2 FROM t3 AS a1 UNION ALL SELECT ARRAY['1'::text] AS c0, 0.5::float8 AS c1, '-3 hours'::interval AS c2 ORDER BY 3) AS kb);
-- pgfuzz:check kernel:exists SELECT CASE WHEN (SELECT count(*) FROM (WITH RECURSIVE rc(c0) AS (SELECT 1 UNION ALL SELECT r.c0 + 1 FROM rc AS r WHERE r.c0 < 100) SELECT ARRAY['1'::text] AS c0, 1.0::float8 AS c1, a1.c3 AS c2 FROM t3 AS a1 UNION ALL SELECT ARRAY['1'::text] AS c0, 0.5::float8 AS c1, '-3 hours'::interval AS c2 ORDER BY 3) AS kb) > 0 THEN (SELECT count(*) FROM (WITH nodes(i, h) AS MATERIALIZED ( SELECT i, i FROM range(256) t(i) ), frontier(i, h) AS MATERIALIZED (VALUES (128, 2)) SELECT* FROM (VALUES (1)) d(delta) JOIN ( FROM frontier) w ON true JOIN nodes n ON w.i + d.delta = n.i AND w.h <= n.h + 1) AS ka) ELSE 0 END
